import { ChangeDetectionStrategy, Component, computed } from "@angular/core";
import { PillComponent } from "./pill.component";

/** A pill for a state of the screen: it reads its label out loud and marks the hint with a question mark. */
@Component({
    selector: "app-status-pill",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill status" [class]="variant()" [attr.aria-label]="spoken()">{{ label() }}@if (!disableTooltip()) {<span class="hint">?</span>}</span>`
})
export class StatusPillComponent extends PillComponent {
    readonly spoken = computed(() => this.disableTooltip() ? this.label() : this.label() + ", a hint is available");
}
