let o = ""; try { o = execSync("npx ngc -p tsconfig.json", {encoding:"utf8", stdio:"pipe"}); } catch (e) { o = e.stdout + e.stderr; }
o = o.replace(/\x1b\[[0-9;]*m/g, "");
const edits = {};
for (const m of o.matchAll(/^(\S+):(\d+):(\d+) - error TS2339: Property 'disableTooltip' does not exist on type '(Fancy|Status)?PillComponent'/gm)) (edits[m[1]] ??= []).push([+m[2], +m[3]]);
let n = 0;
for (const [f, es] of Object.entries(edits)) {
  const lines = fs.readFileSync(f, "utf8").split("\n");
  for (const [l, c] of es.sort((a, b) => b[1] - a[1])) {
    const s = lines[l-1]; if (s.substr(c-1, 14) !== "disableTooltip") throw new Error(f + l);
    lines[l-1] = s.slice(0, c-1) + "hideHint" + s.slice(c+13); n++;
  }
  fs.writeFileSync(f, lines.join("\n"));
}
console.log("ts reads", n);
EOF
node ../fix2.mjs; npx ngc -p tsconfig.json 2>&1 | tail -5; echo "--- remaining member reads:"; grep -rnE "[A-Za-z_)\]?]\.disableTooltip" src | grep -vE "(this\.card\(\)\?|summary)\.disableTooltip\(\)|this\.disableTooltip\b"; echo "--- ref decls:"; grep -rnoE "#\w+" src/app --include=*.html --include=*.ts | awk -F: '{print $NF}' | sort | uniq -c
